def transform(grid):
    """Repair isolated speckles by matching their surrounding region."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    singleton_cells = set()

    # Identify isolated non-background marks using 4-connectivity.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        q.append((ny, nx))
            if len(cells) == 1:
                singleton_cells.add(cells[0])

    # For a one-cell mark, use the color most common in its 8-neighborhood.
    # Also fill a background-colored one-cell hole only when at least six of
    # its eight neighbors agree on a non-background color.
    for r in range(h):
        for c in range(w):
            neighbors = [grid[ny][nx]
                         for dy in (-1, 0, 1) for dx in (-1, 0, 1)
                         if (dy or dx)
                         and 0 <= (ny := r + dy) < h
                         and 0 <= (nx := c + dx) < w]
            counts = Counter(neighbors)
            if (r, c) in singleton_cells:
                best_count = max(counts.values())
                winners = {v for v, n in counts.items() if n == best_count}
                if len(winners) == 1:
                    out[r][c] = winners.pop()
                elif background in winners:
                    winners.remove(background)
                    out[r][c] = next(v for v in neighbors if v in winners)
                else:
                    out[r][c] = next(v for v in neighbors if v in winners)
            elif grid[r][c] == background:
                for color, count in counts.items():
                    if color != background and count >= 6:
                        out[r][c] = color
                        break
    return out


